"""
Writes rtl/font_rom.v from python/font.py, so the hardware font and the Python
screen model can never disagree.   Usage:  python gen_font_rom.py
"""
import os
from font import FONT, CHARS, SPACE

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "..", "rtl", "font_rom.v")


def main():
    lines = [
        "// font_rom.v  (Pierce; extended by Parth in M2)  GENERATED by python/gen_font_rom.py - edit python/font.py",
        "// 5x7 glyphs for the dashboard text. bits[4] is the leftmost pixel of the row.",
        "// Glyph codes: " + ", ".join(f"{i} '{c}'" for i, c in enumerate(CHARS)) + f", {SPACE} space.",
        "// Unknown codes and row 7 are blank.",
        "module font_rom (",
        "    input      [5:0] glyph,",
        "    input      [2:0] row,          // 0 = top",
        "    output reg [4:0] bits",
        ");",
        "    always @* begin",
        "        case ({glyph, row})",
    ]
    for code, ch in enumerate(CHARS):
        for r, bits in enumerate(FONT[ch]):
            if bits != "00000":
                lines.append(f"            {{6'd{code}, 3'd{r}}}: bits = 5'b{bits};   // '{ch}'")
    lines += ["            default: bits = 5'b00000;", "        endcase", "    end", "endmodule", ""]
    with open(OUT, "w", newline="\n") as f:
        f.write("\n".join(lines))
    print(f"wrote {OUT}: {len(CHARS)} glyphs")


if __name__ == "__main__":
    main()
